'use strict';
var uglify = require('uglify-js');
var compose = require('gulp-uglify/composer');
var GulpUglifyError = require('gulp-uglify/lib/gulp-uglify-error');
var logger = require('gulp-uglify/lib/log');

module.exports = function(opts) {
  return compose(
    uglify,
    logger
  )(opts);
};

module.exports.GulpUglifyError = GulpUglifyError;
